  COLYSEUS_OP_DELETE_AND_MOVE(96),
  COLYSEUS_OP_DELETE_AND_ADD(192),
  COLYSEUS_OP_CLEAR(10),
  COLYSEUS_OP_REVERSE(15),
  COLYSEUS_OP_MOVE(32),
  COLYSEUS_OP_MOVE_AND_ADD(160),
