        32 => COLYSEUS_OP_MOVE,
        160 => COLYSEUS_OP_MOVE_AND_ADD,
        33 => COLYSEUS_OP_DELETE_BY_REFID,
        129 => COLYSEUS_OP_ADD_BY_REFID,
        _ =>
          throw ArgumentError("Unknown value for colyseus_operation_t: $value"),
      };
