  external ffi.Pointer<colyseus_sim_part_t> parts;

  @ffi.Int()
  external int part_count;

  @ffi.Double()
  external double smoothing;

  @ffi.Double()
  external double snap;

  @ffi.Double()
  external double step_ms;

  @ffi.Double()
  external double step_seconds;

  @ffi.Int()
  external int sub_steps;

  /// Restore the OPAQUE parts from authority before each replay. Bound parts
  /// are pulled from their sources first, unconditionally. Required when no
  /// part is bound — otherwise there is no restore point and creation fails.
  external ffi.Pointer<
      ffi.NativeFunction<
          ffi.Void Function(ffi.Pointer<colyseus_sim_world_t> world,
              ffi.Pointer<ffi.Void> userdata)>> adopt;

  external ffi.Pointer<
          ffi.NativeFunction<
