      on_reconcile;

  /// Manual pump mode: `step` may be NULL, the host drains steps through
  /// colyseus_reconciler_pump_*() (see reconciler.h).
  @ffi.Bool()
  external bool manual_step;

  external ffi.Pointer<ffi.Void> userdata;
}

